        // We need to read storage directly since there's no public getter for tradingActive
        // Let's try a different approach - check if we can execute a transfer

        // Get some tokens first using deal()
        uint256 initialTokens = 100_000_000 * 1e18;
        deal(TARGET, attacker, initialTokens);

        console.log("Attacker initial balance:", MarvinInu(TARGET).balanceOf(attacker));

        // Get the Uniswap pair address
